package docs

import _ "embed"

// The generated artifacts, embedded into the binary rather than read from disk: a
// release image ships the binary only, so a spec read at runtime would be a file
// that is not there — and, worse, one that anyone with write access to the
// deployment directory could swap for a different description of the API.
//
// Regenerated by `bash scripts/release-gate/openapi.sh gen internal/docs`
// (doc/310 §12.1); freshness is checked by s25.openapi-freshness.
//
//go:embed swagger.json
var OpenAPISpecJSON []byte

//go:embed swagger.yaml
var OpenAPISpecYAML []byte
